using MediatR;using Namaa.Application.Abstractions.Persistence;using Namaa.Application.PaymentVouchers.Dtos;using Namaa.Domain.Common.Errors;using Namaa.Domain.Common.Results;namespace Namaa.Application.PaymentVouchers.Queries.GetPaymentVoucherById;public sealed class GetPaymentVoucherByIdQueryHandler(IPaymentVoucherRepository repository):IRequestHandler<GetPaymentVoucherByIdQuery,Result<PaymentVoucherDto>>{public async Task<Result<PaymentVoucherDto>>Handle(GetPaymentVoucherByIdQuery request,CancellationToken cancellationToken){var e=await repository.FindByIdAsync(request.Id,cancellationToken);return e is null?Result.Failure<PaymentVoucherDto>(PaymentVoucherErrors.NotFound):Result.Success(PaymentVoucherDto.FromEntity(e));}}
